(4, '', 'ASA2017010208000023982785', 'ASA', 'DESFILE CIVICO ANIVERSARIO DISTRITO DE SAN SEBASTIAN 2017', 0, 0, 'DESFILE CIVICO  DE PARTICIPACION OBLIGATORIO  DE TODOS LOS SOCIOS', '2017-01-02', '08:00:00', 'PLAZA DE ARMAS', 0.00, 5.00, 0.00, '0000-00-00', 'CTA002-EB1', 'ASA2017010208000023982785.json', '', '2017-01-02', '07:43:05', '23982785'),
(7, '', 'ASA2017043008300023982785', 'ASA', '2DA ASAMBLEA GENERAL ORDINARIA - 30 ABRIL 2017', 0, 0, 'COMUNICADO: 003-2017-ARP\r\nSE LES COMUNICA A TODOS LOS SOCIOS DE LA ASOCIACION RESIDENCIAL EL PARAISO QUE LA ASAMBLEA GENERAL DEL DIA 30 DE ABRIL SE REALIZARA CON LA SIGUENTE PROGRAMACION:\r\nASAMBLEA GENERAL 30 DE ABRIL DEL 2017\r\nPRIMERA CITACION: 8:30 AM \r\nSEGUNDA CITACION 9:00 AM (INICIO DE ASAMBLEA)\r\nAGENDA DE ASAMBLEA GENERAL 30 DE ABRIL -2017\r\n1.-INFORME LEGAL DE LA ASOCIACION\r\n2.-INFORME TECNICO DE AVANCES\r\n3.-TOMA DE POSECION DE LOTES ENTREGADO\r\nNOTA: A TODOS LOS SOCIOS DE LA ASOCIACION SE LES COMUNICA QUE LA MOBILIDAD AL TERRENO PARTIRA A LAS 7:AM DE AGUA BUENA SE LES RECOMIENDA SER PUNTUALES. CUALQUIER CONSULTA POR FAVOR COMUNICARSE CON LA UNICA OFICINA TLF: 084-276403\r\nATTE. LA DIRECTIVA', '2017-04-30', '08:30:00', 'PLAZA DE ARMAS - ASOCIACION', 10.00, 10.00, 0.00, '0000-00-00', 'CTA003-EB1', 'ASA2017043008300023982785.json', '', '2017-04-29', '18:25:10', '23982785'),
